                "stdout": "==========================================================================================\nFILE: /Users/jinxianyu/code/ai-agent-practical/src/ai_agent_practical/_reference_solution/__init__.py\n==========================================================================================\n\"\"\"本地小模型 Agent 的最小骨架（对应《深入理解 AI Agent》第二章 实验 2-1）。\n\n核心公式：Agent = LLM + 上下文 + 工具。本包用最少的代码把这三件事跑通：\n\n- LLM   —— 本机 Ollama 里的小模型（默认 qwen3:0.6b，约 523 MB）\n- 上下文 —— LocalAgent.messages，每轮把助手回复和工具结果追加进去\n- 工具   —— ToolRegistry 里注册的 name + description + JSON Schema\n\n与书上完整实验的区别：这里刻意去掉了 vLLM 后端、多后端探测、PDF/代码解释器\n等重型依赖，只保留 ollama + requests 两个依赖，方便在 macOS 上快速跑通。\n\n模块：\n    tools  —— 工具注册表与两个示例工具\n    agent  —— LocalAgent：ReAct 循环与流式事件\n    main   —— 命令行入口\n\"\"\"\n\nfrom .agent import LocalAgent\nfrom .tools import ToolRegistry, build_default_registry\n\n__all__ = [\"LocalAgent\", \"ToolRegistry\", \"build_default_registry\"]\n\n\n==========================================================================================\nFILE: /Users/jinxianyu/code/ai-agent-practical/src/ai_agent_practical/_reference_solution/tools.py\n==========================================================================================\n\"\"\"工具：给模型看的「说明书」+ 真正执行的 Python 函数。\n\n关键认知：模型看不到下面这些函数的实现，它只看到 name / description /\nparameters(JSON Schema)。所以 description 写得越清楚具体，小模型选工具\n选得越准 —— 这正是「上下文决定 Agent 能力上限」的直接体现。\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections.abc import Callable\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom typing import Any\nfrom zoneinfo import ZoneInfo\n\nimport requests\n\n\n@dataclass\nclass Tool:\n    \"\"\"一个工具的三要素：模型通过前三个字段决定「调不调、怎么调」。\"\"\"\n\n    name: str\n    description: str\n    parameters: dict[str, Any]\n    func: Callable[..., str]\n\n\nclass ToolRegistry:\n    \"\"\"工具注册表：负责把工具转成模型能读的 schema，并按名字执行。\"\"\"\n\n    def __init__(self) -> None:\n        self._tools: dict[str, Tool] = {}\n\n    def register(self, tool: Tool) -> None:\n        self._tools[tool.name] = tool\n\n    def schemas(self) -> list[dict[str, Any]]:\n        \"\"\"转成 Ollama / OpenAI 通用的 tools 字段格式。\"\"\"\n        return [\n            {\n                \"type\": \"function\",\n                \"function\": {\n                    \"name\": tool.name,\n                    \"description\": tool.description,\n                    \"parameters\": tool.parameters,\n                },\n            }\n            for tool in self._tools.values()\n        ]\n\n    def call(self, name: str, arguments: dict[str, Any]) -> str:\n        \"\"\"执行工具，把结果转成字符串回填给模型。\n\n        工具自己报错时不要把异常抛出去 —— 把错误信息当成观察结果还给模型，\n        模型有机会自己改参数重试。\n        \"\"\"\n        tool = self._tools.get(name)\n        if tool is None:\n            return f\"错误：不存在名为 {name} 的工具\"\n        try:\n            return tool.func(**arguments)\n        except Exception as exc:  # noqa: BLE001 - 工具报错也要回给模型\n            return f\"工具执行失败：{exc}\"\n\n\ndef get_current_time(timezone: str = \"UTC\") -> str:\n    \"\"\"查询指定时区的当前时间。只依赖标准库。\"\"\"\n    now = datetime.now(ZoneInfo(timezone))\n    return now.strftime(\"%Y-%m-%d %H:%M:%S %Z\")\n\n\ndef get_current_temperature(city: str) -> str:\n    \"\"\"查询城市实时气温。用 Open-Meteo，免费且不需要 API Key。\n\n    两步：地名 → 经纬度（geocoding）→ 当前气温（forecast）。\n    这种「后一步依赖前一步结果」的情形，模型只能在下一轮再发起调用。\n    \"\"\"\n    geo = requests.get(\n        \"https://geocoding-api.open-meteo.com/v1/search\",\n        params={\"name\": city, \"count\": 1},\n        timeout=10,\n    ).json()\n    if not geo.get(\"results\"):\n        # 报错信息也是「观察结果」，会进入上下文影响模型下一步动作。\n        # 所以这里不只报告失败，还明确告诉模型该怎么改参数重试 ——\n        # 这正是 ReAct 循环里「工具结果反过来指导行动」的体现。\n        return (\n            f\"找不到城市「{city}」。该接口只认英文或拼音地名，\"\n            f\"请改用英文名重新调用，例如 Tokyo、Shanghai、Vancouver。\"\n        )\n\n    hit = geo[\"results\"][0]\n    weather = requests.get(\n        \"https://api.open-meteo.com/v1/forecast\",\n        params={\n            \"latitude\": hit[\"latitude\"],\n            \"longitude\": hit[\"longitude\"],\n            \"current\": \"temperature_2m\",\n        },\n        timeout=10,\n    ).json()\n    return (\n        f\"{hit['name']}（{hit.get('country', '')}）当前气温 \"\n        f\"{weather['current']['temperature_2m']}°C\"\n    )\n\n\ndef build_default_registry() -> ToolRegistry:\n    \"\"\"注册骨架默认带的两个工具。想看模型如何选择工具，从这两个的描述改起。\"\"\"\n    registry = ToolRegistry()\n    registry.register(\n        Tool(\n            name=\"get_current_time\",\n            description=(\n                \"查询指定时区的当前日期和时间。\"\n                \"时区使用 IANA 名称，例如 Asia/Shanghai、America/New_York、Europe/London。\"\n            ),\n            parameters={\n                \"type\": \"object\",\n                \"properties\": {\n                    \"timezone\": {\n                        \"type\": \"string\",\n                        \"description\": \"IANA 时区名，例如 Asia/Shanghai；不传则按 UTC\",\n                    }\n                },\n                \"required\": [],\n            },\n            func=get_current_time,\n        )\n    )\n    registry.register(\n        Tool(\n            name=\"get_current_temperature\",\n            description=(\n                \"查询某个城市的实时气温（摄氏度）。数据来自 Open-Meteo，无需 API Key。\"\n                \"注意：city 必须是英文或拼音地名（如 Tokyo、Shanghai），不支持中文名。\"\n            ),\n            parameters={\n                \"type\": \"object\",\n                \"properties\": {\n                    \"city\": {\n                        \"type\": \"string\",\n                        \"description\": \"城市英文名，例如 Tokyo、Shanghai、Vancouver\",\n                    }\n                },\n                \"required\": [\"city\"],\n            },\n            func=get_current_temperature,\n        )\n    )\n    return registry\n\n\n==========================================================================================\nFILE: /Users/jinxianyu/code/ai-agent-practical/src/ai_agent_practical/_reference_solution/agent.py\n==========================================================================================\n\"\"\"LocalAgent：Ollama + 工具调用 + ReAct 循环的最小实现。\n\n只保留一条正确路径（流式 ReAct 循环），刻意不做非流式分支 —— 书里\n非流式实现只处理一轮工具调用，多步任务会提前收尾，对学习者是个干扰。\n\n事件类型（chat() 逐条产出，交给上层决定怎么显示）：\n    thinking     模型的内部思考（仅带思维链的模型会有）\n    tool_call    模型请求调用某工具，含解析后的参数\n    tool_result  工具执行结果（即 ReAct 里的「观察」）\n    content      给用户的正式回复\n    error        异常或超过最大步数\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nfrom collections.abc import Iterator\nfrom concurrent.futures import ThreadPoolExecutor\nfrom typing import Any\n\nimport ollama\n\nfrom .tools import ToolRegistry, build_default_registry\n\nEvent = dict[str, Any]\n\n\nclass LocalAgent:\n    \"\"\"把「模型选择工具 → 执行 → 回填结果 → 再决策」这个循环封装成一个 chat()。\"\"\"\n\n    def __init__(\n        self,\n        model: str = \"qwen3:0.6b\",\n        tools: ToolRegistry | None = None,\n        temperature: float = 0.3,\n        max_steps: int = 8,\n        think: bool | None = None,\n    ) -> None:\n        self.model = model\n        self.temperature = temperature\n        self.max_steps = max_steps  # ReAct 最多循环几轮，防止小模型反复调同一个工具\n        # think 是「要不要思维链」的开关，不是「思考存到哪个字段」：\n        # None = 用模型默认（qwen3 默认开）；True / False = 强制开 / 关。\n        # 关掉能省 token 和延迟，但会失去最直观的调试线索。\n        self.think = think\n        self.registry = tools or build_default_registry()\n        # client 只是 HTTP 客户端，默认连 http://127.0.0.1:11434；\n        # 模型权重由 Ollama 服务端在第一次请求时才加载进内存。\n        self.client = ollama.Client()\n        self.messages: list[dict[str, Any]] = []  # 上下文：模型唯一的记忆\n\n    # ------------------------------------------------------------------ 公开接口\n\n    def available_models(self) -> list[str]:\n        \"\"\"列出本机已下载的模型，供启动前校验（避免拿到一个看不懂的 404）。\"\"\"\n        return [m.model for m in self.client.list().models]\n\n    def reset(self) -> None:\n        \"\"\"清空上下文。上下文是模型唯一的记忆，清掉即彻底失忆。\"\"\"\n        self.messages.clear()\n\n    def chat(self, message: str) -> Iterator[Event]:\n        \"\"\"跑一轮完整对话，逐条产出事件。这是一个生成器，边跑边 yield。\"\"\"\n        self.messages.append({\"role\": \"user\", \"content\": message})\n\n        for _ in range(self.max_steps):\n            text_parts: list[str] = []\n            pending: list[dict[str, Any]] = []  # 本轮模型请求的所有工具调用\n\n            # ── 第 1 步：把消息 + 工具定义发给模型，边收边转发 ──\n            request: dict[str, Any] = {\n                \"model\": self.model,\n                \"messages\": self.messages,\n                \"tools\": self.registry.schemas(),\n                \"options\": {\"temperature\": self.temperature},\n                \"stream\": True,\n            }\n            if self.think is not None:\n                request[\"think\"] = self.think\n\n            for chunk in self.client.chat(**request):\n                msg = chunk.get(\"message\", {})\n\n                if msg.get(\"thinking\"):\n                    yield {\"type\": \"thinking\", \"content\": msg[\"thinking\"]}\n                if msg.get(\"content\"):\n                    text_parts.append(msg[\"content\"])\n                    yield {\"type\": \"content\", \"content\": msg[\"content\"]}\n\n                for call in msg.get(\"tool_calls\") or []:\n                    # 某些服务端会在每个 chunk 里重复发送累积的工具列表，需去重\n                    if call not in pending:\n                        pending.append(call)\n                        yield {\"type\": \"tool_call\", \"content\": call[\"function\"]}\n\n            assistant: dict[str, Any] = {\n                \"role\": \"assistant\",\n                \"content\": \"\".join(text_parts),\n            }\n\n            # ── 第 2 步：模型不再请求工具 = 它认为信息够了，循环结束 ──\n            if not pending:\n                self.messages.append(assistant)\n                return\n\n            # ── 第 3 步：把「助手说了什么 + 要调什么」原样记入上下文，再执行工具 ──\n            # 原样保留（而不是只存文本）才能满足多轮消息契约，也让下一轮请求\n            # 的消息前缀与这一轮严格一致 —— 这是 KV Cache 能复用的前提。\n            assistant[\"tool_calls\"] = pending\n            self.messages.append(assistant)\n\n            # ── 第 4 步：执行工具，把观察结果回填，然后回到循